#' Covariate Balance
#'
#' 
#' @param data .
#' @param treat .
#' @param covs .
#' @param weights .
#' @param adjW .
#' @param adjust .
#' @param estimand .
#' @param link .
#' @param moments .
#' @param denom .
#' @param stdBinary .
#' @param threshold .
#' @param showMeans .
#' @param showVr .
#' @param showKs .
#' @param plot .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$bal} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$lovePlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$summary$asDF}
#'
#' \code{as.data.frame(results$summary)}
#'
#' @export
balance <- function(
    data,
    treat,
    covs,
    weights,
    adjW,
    adjust = "ipw",
    estimand = "ate",
    link = "logit",
    moments = "m1",
    denom = "auto",
    stdBinary = TRUE,
    threshold = 0.1,
    showMeans = TRUE,
    showVr = TRUE,
    showKs = TRUE,
    plot = TRUE,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("balance requires jmvcore to be installed (restart may be required)")

    if ( ! missing(treat)) treat <- jmvcore::resolveQuo(jmvcore::enquo(treat))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if ( ! missing(weights)) weights <- jmvcore::resolveQuo(jmvcore::enquo(weights))
    if ( ! missing(adjW)) adjW <- jmvcore::resolveQuo(jmvcore::enquo(adjW))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(treat), treat, NULL),
            `if`( ! missing(covs), covs, NULL),
            `if`( ! missing(weights), weights, NULL),
            `if`( ! missing(adjW), adjW, NULL))


    options <- balanceOptions$new(
        treat = treat,
        covs = covs,
        weights = weights,
        adjW = adjW,
        adjust = adjust,
        estimand = estimand,
        link = link,
        moments = moments,
        denom = denom,
        stdBinary = stdBinary,
        threshold = threshold,
        showMeans = showMeans,
        showVr = showVr,
        showKs = showKs,
        plot = plot,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- balanceClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

